Terrain_Forest is TModule
(
    // YMB-1234 marker
    Calc = nil // YSM-old
    Speed = TAmmo
    (
        Ammo                    = nil
    )
    Tags = 1000000
    Damage                    = TAmmo
    (
        Ratio = EFlag/A | EFlag/B | EFlag/C // it's
        Big                    = TAmmo
        (
            Damage                    = 'with // slashes'
            Ammo is -Speed
        )
        Damage                    = nil
        Calc                    = [5., 5 * 60, True]
        Speed                    = EFlag/A | EFlag/B | EFlag/C /* block */
        Tags                    = $/GFX/Weapon/Weapon_Gun
    ) // note
    Big                    = TWeapon(
        Name                    = TWeapon
        (
            /* two
   lines */
