            Damage                    = True
            Big = 10 div 3
            Salves = 0.1
        )
        Salves = (nil, False)
        Ratio                    = ('Text', EFlag/Fast)
    ) /* block */
    // note
    Speed                    = nil
    Ratio                    = <Ref>
)

