unnamed TWeapon(
	Tags					= -Speed
	Pairs					= [
		<Ref>,
		/* two
   lines */
		$/GFX/Weapon/Ammo_B,
		TAmmo
		(
			Damage					= 123456789012345678 // YSM-old
			Pairs					= GUID:{fa80d57f-4697-297b-7cdd-8fde41286c61} // YSM-old
			Speed					= 100
			// YMB-ORIGINAL
			Calc = nil
			// YMB-ORIGINAL
			Salves = GUID:{87f559c7-1cbf-d2df-bd3c-a8167e2f26ac}
			Name					= 5 * 60
			Ammo = GUID:{8e87d47f-9101-c879-04c6-454172f93619}
		),
		TModule
		(
			Salves					= "Quoted text"
			Pairs					= EFlag/Fast // YMB-1234 marker
			// YMB-1234 marker
			Calc = 'Text'
			Damage = $/GFX/Weapon/Ammo_DCA_1
			/* block */
			Tags					= "Quoted text"
		), // note
	]
	Big = TWeapon(
		Damage = Inner is $/GFX/Weapon/Weapon_Gun2
		Ammo					= <Ref>
		Name = TModule(
			Big = 0.25
			Name = "Quoted text"
			Salves is 0.25 // note
		)
		Pairs					= True
		Salves = True
		/* two
   lines */
		Calc = 'with // slashes'
	)
	// a "quoted" // comment
	Name					= RGBA[
		Inner is EFlag/Fast, // note
	]
	Big					= TTerrain(
		Salves					= EFlag/A | EFlag/B /* a */ /* b */
		Big = "Quoted text"
		Speed = -Speed
		Big = TWeapon(
			// YMB-ORIGINAL
			Big = 100
			Tags					= 10 div 3
			//
			Ammo = 9007199254740993
			Big = 5 * 60
			Name = (2 + 3)
			Tags					= MyConstant
			Speed					= 7
		)
		Calc					= TAmmo
		(
			Speed = "Quoted text"
			Name					= 9007199254740993
			Big = (2 + 3)
			Pairs					= -Speed
			Ammo					= 'with // slashes'
			Damage is False
			Ammo = GUID:{af1f815b-863c-2431-53e6-c904efc3edb3}
		)
		// note
		Tags					= 'Text'
		Pairs = EFlag/A | EFlag/B | EFlag/C
		Calc					= TAmmo(
			Name					= 5 * 60
		)
	)
)
